    cs=[c for c in range(w) if any(grid[r][c]==8 for r in range(h))]
    if not rs or not cs:
        return out
    rbase, cbase = min(rs), min(cs)
    for r0 in range(rbase, h, 2):
        for c0 in range(cbase, w, 2):
            pos=[(dr,dc) for dr in range(2) for dc in range(2)
                 if r0+dr<h and c0+dc<w and grid[r0+dr][c0+dc]==8]
            if not pos:
                continue
            p=set(pos)
            if len(p)==4:
                color=1
            elif p=={(0,1),(1,0),(1,1)}:
                color=2
            elif p=={(0,0),(1,0),(1,1)}:
                color=4
            elif p=={(0,0),(0,1),(1,1)}:
                color=3
            elif p=={(0,0),(0,1),(1,0)}:
                color=2
            elif len(p)==2:
                color=3 if {a for a,b in p}=={1} else 4 if {a for a,b in p}=={0} else 2
            else:
                color=2
            for dr,dc in p:
                out[r0+dr][c0+dc]=color
    return out
